// SLF4J の「レベル判定」と「{} の遅延評価」をまねた、ごく小さなロガー
enum Level { TRACE, DEBUG, INFO, WARN, ERROR }

class MiniLogger {
    final Level threshold;
    MiniLogger(Level threshold) { this.threshold = threshold; }

    boolean isEnabled(Level level) {
        // enum は宣言順に並ぶので、設定レベル以上なら出す
        return level.compareTo(threshold) >= 0;
    }
    // 連結済みの文字列を受け取る版
    void debug(String message) {
        if (isEnabled(Level.DEBUG)) {
            System.out.println("DEBUG " + message);
        }
    }
    // {} 版:出すと決まってから toString する
    void debug(String format, Object arg) {
        if (isEnabled(Level.DEBUG)) {
            String text = format.replace("{}", String.valueOf(arg));
            System.out.println("DEBUG " + text);
        }
    }
}

// toString が呼ばれた回数を数えるクラス
class Order {
    static int toStringCalls = 0;
    final int id;
    Order(int id) { this.id = id; }
    @Override public String toString() {
        toStringCalls++;
        return "Order#" + id;
    }
}

// ここを変えてみよう:Level.INFO を Level.DEBUG や Level.WARN に
// DEBUG にするとログが出て、{} 版でも toString が呼ばれるようになる
var log = new MiniLogger(Level.INFO);

for (int i = 1; i <= 5; i++) {
    log.debug("連結で処理: " + new Order(i));
}
System.out.println("連結版の toString 呼び出し: " + Order.toStringCalls + " 回");

Order.toStringCalls = 0;
for (int i = 1; i <= 5; i++) {
    log.debug("{} を処理", new Order(i));
}
System.out.println("{} 版の toString 呼び出し: " + Order.toStringCalls + " 回");

